import{_ as a,o as e,c as s,ai as n}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"第一天可以试的 5 件事","description":"五个低风险、见效快的练手任务，帮你在一天内摸清 Grok Bot 的能力边界。","frontmatter":{"related":["/basics/cloud-computer","/basics/drafts-first","/automation/routines"],"title":"第一天可以试的 5 件事","description":"五个低风险、见效快的练手任务，帮你在一天内摸清 Grok Bot 的能力边界。","section":"start","order":4,"tags":["入门","实践","示例"],"sources":["https://docs.x.ai/grok-bot/overview","https://docs.x.ai/grok-bot/chat-and-collaboration","https://cursor.com/docs/grok-bot/work"],"wordCount":440,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"第一天可以试的 5 件事 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"五个低风险、见效快的练手任务，帮你在一天内摸清 Grok Bot 的能力边界。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/start/five-things-day-one"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/start-five-things-day-one-11d144fe90.png"}],["meta",{"property":"og:image:alt","content":"第一天可以试的 5 件事 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"第一天可以试的 5 件事 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"五个低风险、见效快的练手任务，帮你在一天内摸清 Grok Bot 的能力边界。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/start-five-things-day-one-11d144fe90.png"}],["meta",{"name":"twitter:image:alt","content":"第一天可以试的 5 件事 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/start/five-things-day-one"}]]},"headers":[],"relativePath":"start/five-things-day-one.md","filePath":"start/five-things-day-one.md","lastUpdated":1792485206000}'),o={name:"start/five-things-day-one.md"};function i(p,t,l,r,c,d){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="第一天可以试的-5-件事" tabindex="-1">第一天可以试的 5 件事 <a class="header-anchor" href="#第一天可以试的-5-件事" aria-label="Permalink to &quot;第一天可以试的 5 件事&quot;">​</a></h1><p>第一天的目标不是&quot;自动化一切&quot;，而是<strong>摸清它能做什么、做到什么程度、在哪里会停下来问你</strong>。下面五件事都是只读或只出草稿的，风险很低。</p><h2 id="_1-整理一份资料包" tabindex="-1">1. 整理一份资料包 <a class="header-anchor" href="#_1-整理一份资料包" aria-label="Permalink to &quot;1. 整理一份资料包&quot;">​</a></h2><p>找一个你最近在关注的话题，让它上网查资料并整理成文件。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我调研&quot;中小团队如何做知识库&quot;这个话题，找 6-8 篇有代表性的公开文章。</span></span>
<span class="line"><span>整理成一份 Markdown 文档：每篇写来源链接、核心观点（3 条以内）、适合什么规模的团队。</span></span>
<span class="line"><span>最后附一段 300 字以内的综合建议。文件保存好后发给我。</span></span></code></pre></div><p>观察点：它怎么用浏览器、怎么在云电脑上保存文件、交付的文件卡片长什么样。</p><h2 id="_2-处理你手上的一个文件" tabindex="-1">2. 处理你手上的一个文件 <a class="header-anchor" href="#_2-处理你手上的一个文件" aria-label="Permalink to &quot;2. 处理你手上的一个文件&quot;">​</a></h2><p>把一份表格或 PDF 直接拖进对话。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>附件是上个月的费用明细。帮我按类别汇总金额，找出金额最大的 5 笔，</span></span>
<span class="line"><span>再生成一个新的 Excel，包含汇总表和明细表。不要改动原文件。</span></span></code></pre></div><h2 id="_3-写一封邮件草稿" tabindex="-1">3. 写一封邮件草稿 <a class="header-anchor" href="#_3-写一封邮件草稿" aria-label="Permalink to &quot;3. 写一封邮件草稿&quot;">​</a></h2><p>连接邮箱后试一次&quot;只出草稿&quot;。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我给合作方写一封邮件，确认下周三下午的会议，并附上议程三点：……</span></span>
<span class="line"><span>语气礼貌简洁。先出草稿给我看，不要发送。</span></span></code></pre></div><p>你会看到一张可编辑的草稿卡片，确认收件人和正文后，由你自己按发送。</p><h2 id="_4-让它记住一条偏好" tabindex="-1">4. 让它记住一条偏好 <a class="header-anchor" href="#_4-让它记住一条偏好" aria-label="Permalink to &quot;4. 让它记住一条偏好&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以后给我的所有总结：先写结论，再写理由；能用表格就用表格；不要用感叹号。请记住。</span></span></code></pre></div><p>隔一会儿再让它总结点东西，看看它是否照做。</p><h2 id="_5-设一个小小的定时提醒" tabindex="-1">5. 设一个小小的定时提醒 <a class="header-anchor" href="#_5-设一个小小的定时提醒" aria-label="Permalink to &quot;5. 设一个小小的定时提醒&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个工作日早上 9 点，帮我列出今天日历上的会议和需要提前准备的材料，发在这个对话里。</span></span>
<span class="line"><span>先测试运行一次给我看效果。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">用语音也可以</p><p>不方便打字时，可以用语音输入，或者直接开语音对话。Bot 有时也会回一段语音备忘，点开就能听，还能展开看文字。</p></div><div class="warning custom-block"><p class="custom-block-title">测试运行是真的在干活</p><p>例程的&quot;测试&quot;会真实执行：打开网页、读写文件、调用已连接的应用。所以第一批例程最好只做读取和整理，不要涉及发送和删除。</p></div><h2 id="一天结束时-问自己三个问题" tabindex="-1">一天结束时，问自己三个问题 <a class="header-anchor" href="#一天结束时-问自己三个问题" aria-label="Permalink to &quot;一天结束时，问自己三个问题&quot;">​</a></h2><ul><li>哪件事它做得比我预期好？——这类事可以多交给它。</li><li>哪件事它反复做错？——是我没说清，还是缺少数据源或权限？</li><li>哪件事我明天还要再做一遍？——这就是第一个技能或例程的候选。</li></ul>`,22)])])}const u=a(o,[["render",i]]);export{g as __pageData,u as default};
